INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(40000, 0, 400, 0, 0, 0, 'Thousand Needles', 'Thousand Needles is a deep canyon in southern Kalimdor, lying below the cliffs at the southern edge of the Barrens and running east to salt flats on the border of Tanaris, with Feralas beyond its western rim. It takes its name from the dozens of tall columns of sandstone that rise from the dry canyon floor. Tauren make their homes on the high mesas, out of reach of the centaur war bands below, climbing to them by lifts and crossing between the spires on rope bridges. The Great Lift carries travelers down from the Barrens, and the Horde holds Freewind Post high atop a mesa. The Galak centaur raid from Camp E''thok and Splithoof Crag, a band of the Grimtotem tribe keeps its secrets on Darkcloud Pinnacle, harpies screech in the western ravines and wyverns nest at Highperch. In the east lie the Shimmering Flats, a blinding salt plain below the level of the sea, where gnomes and goblins race rocket cars and dwarves dug too deep and woke a silithid hive.', 'warcraft.wiki.gg/wiki/Thousand_Needles (pre-Cataclysm geography: sandstone columns cut by water, bridges across spires, tauren on mesas, centaur war bands, Shimmering Flats below sea level, Mirage Raceway); warcraft.wiki.gg/wiki/Freewind_Post (lifts and rope bridges); quest 1196 description (Great Lift at the southern edge of the Barrens); quest 9433 description (Thalanaar on the western edge); quest 1146 description (silithid erupted from a cave at the dig site)'),
(40001, 1, 400, 1, 0, 0, 'The Great Lift', 'At the southern edge of the Barrens the land drops away in sheer cliffs, and the Great Lift, an elevator built by the tauren, carries travelers down to the floor of Thousand Needles. Tauren braves keep watch over it. Brave Moonhorn warns that the centaurs have stepped up their attacks and that the nearby Grimtotem have been acting strangely. Grish Longrunner has guarded the lift so long that he wants only leave to visit his family. Not far away lies the body of a dwarf, Henrig Lonebrow, his weathered journal still with him. Its pages tell of the boar men of Razorfen Kraul who took him captive, and of the dying night elf who shared his cell.', 'warcraft.wiki.gg/wiki/Great_Lift (tauren built elevator between the Barrens and Thousand Needles; dead dwarf Henrig Lonebrow nearby); quest 4542 description (Brave Moonhorn); quest 5881 description and reward text (Grish Longrunner); gameobject 19861 Henrig Lonebrow''s Journal in area 485; item 5790 page_text 424-431; quest 1100 reward text (journal found on a deceased dwarf); zone_areas: Grish 12576, Moonhorn 10079, Mesa Elevators in 485'),
(40002, 1, 400, 2, 0, 0, 'Darkcloud Pinnacle', 'East of the Great Lift, three small mesas form Darkcloud Pinnacle, home of a band of the Grimtotem tribe. Rope bridges join the mesas, and the only two ways in are well guarded. Stompers, geomancers and bandits hold its heights, the fearsome Harb Foulmountain roams among them, and the outcast Arnak Grimtotem, wanted at Freewind Post for murder, was last seen on the cliffs nearby. The Grimtotem here keep secrets. Three agents of unknown origin have visited them, and their guarded messages lie in chests within the pinnacle. On an isolated needle where the tribe lays its dead rests the dormant Sacred Fire of Life. Nearby lies the Boiling Pool, where elementals stir and the rare Incendia agave grows.', 'warcraft.wiki.gg/wiki/Darkcloud_Pinnacle (east of the Great Lift, three small mesas, slope and bridge entrances well guarded, leaders Arnak Grimtotem and Harb Foulmountain, secret correspondence); quest 5064 description (three agents of unknown origin; chests in Darkcloud Pinnacle); page_text 2232-2234 (Secret Notes); quest 5088 description (isolated needle where they bury their dead); quest 5062 description and reward text (Boiling Pool, Incendia agave, dormant sacred fire); zone_areas 2097: Grimtotem Stomper, Geomancer, Reaver, Bandit, Boiling and Scalding Elementals, Incendia Agave, Sacred Fire of Life, Document Chests; creature 14426 Harb Foulmountain (rare, faction 16) spawned in area 2097; quest 5147 description (Arnak the outcast); creature_text 10646 (strange power over the Grimtotem); quest 5147 description (wanted for murder and kidnapping, last seen on the cliffs near the pinnacle)'),
(40003, 1, 400, 3, 0, 0, 'Camp E''thok', 'Camp E''thok is a camp of the Galak centaur in the northwest of the canyon, not far from the road that runs past Whitereach Post. From here the centaurs strike at caravans and travelers on the road, and the goblin Wizlo Bearingshiner was the only one to live through their attack on his. Stormers, maulers and marauders hold the camp, ready to ride out at a moment''s notice. Pesterhide hyenas skulk about the camp as well, among them Steelsnap, the tyrant of the pack, whom the hunters of Thunder Bluff send their champions to slay.', 'warcraft.wiki.gg/wiki/Camp_E''thok (Galak camp in northwestern Thousand Needles; centaurs raided Wizlo Bearingshiner''s caravan); warcraft.wiki.gg/wiki/Whitereach_Post (along the road near Camp E''thok); quest 5151 description; quest 1131 description (Steelsnap); zone_areas 480: Galak Stormer, Mauler, Marauder, Pesterhide Snarler, Steelsnap 4548; thunder_bluff.json 163819 (Steelsnap hunt told there)'),
(40004, 1, 400, 4, 0, 0, 'Whitereach Post', 'Whitereach Post is a small Horde camp beside the road in the northwest of the canyon, close to the Galak of Camp E''thok. The tauren Kanati Greycloud keeps a hunting camp here, at the very edge of centaur country. Motega Firemane brought young Pao''ka Swiftmountain to Thousand Needles to study the creatures that live in these lands, and he knows the old legends of his people as well as its beasts. Laer Stepperunner sells food and drink to passing travelers. The goblin Wizlo Bearingshiner stays here too, the lone survivor of a centaur raid on his caravan just to the north.', 'warcraft.wiki.gg/wiki/Whitereach_Post (small Horde camp along the road near Camp E''thok; residents); quest 4881 description (Kanati bold to set up a hunting camp); quest 4770 reward text (Motega and Pao''ka came to study creatures); quest 4865 reward text (Motega knows the legend of Arikara); quest 5151, 9433 descriptions (Wizlo); zone_areas 2237: Kanati 10638, Motega 10428, Wizlo 10941, Laer 3689, Robotron 3000 17178'),
(40005, 1, 400, 5, 0, 0, 'Highperch', 'Highperch is a raised stretch of the far western canyon, reached by a ramp along the canyon walls northwest of Freewind Post, and it is the nesting ground of the proud Highperch wyverns. Patriarchs, consorts and soarers guard nests full of eggs, sun scorched shells lie among the rocks, and the rare Heartrazor hunts here. The Horde prizes these beasts. At Freewind Post the apprentice Elu gathers Highperch eggs, since the master wind riders cannot train wyverns fast enough to keep up with the demand. Those who come too close pay for it. Young Pao''ka Swiftmountain crept in to study the wyverns, was chased off a nest, and hid in the heights for days, lost and alone.', 'warcraft.wiki.gg/wiki/Highperch (elevated western area; the proud Highperch wyverns); quest 4767 description (Elu, eggs for the master wind riders, ramp northwest along the canyon walls); quest 4770 description (Pao''ka); zone_areas 482: Highperch Wyvern, Consort, Patriarch, Soarer, Heartrazor 5934, Highperch Wyvern Egg, Sunscorched Shell'),
(40006, 1, 400, 6, 0, 0, 'Splithoof Crag', 'Splithoof Crag is the chief village of the Galak centaur, set against the northern wall of the canyon north of Freewind Post. Scouts, wranglers and windchasers crowd its slopes, and the tauren of Freewind live close by in the shadow of their raids. In the heart of the crag a heavily guarded cavern, Splithoof Hold, keeps the tribe''s greatest treasure: the Cloven Hoof, a relic from the time of the centaurs'' creation, held within an eternal flame.', 'warcraft.wiki.gg/wiki/Splithoof_Crag (Galak village against the northern wall; Splithoof Hold cavern guarding the Cloven Hoof); warcraft.wiki.gg/wiki/Galak (larger of the two villages); quest 1197 description (Splithoof Crag north of Freewind, flame kept in Splithoof Hold); quest 1195 description, 1196 reward text (artifact from the centaurs'' creation, shared ancestry, eternal flame); quest 4542 reward text and 4841 description and objectives; zone_areas 481: Galak Windchaser, Wrangler, Scout; WMOAreaTable maps the cave to 1557'),
(40007, 1, 400, 7, 0, 0, 'Freewind Post', 'Freewind Post is the Horde''s stronghold in Thousand Needles, a tauren village high atop a mesa, out of reach of the centaur war bands below. Wooden lifts carry visitors up, and rope bridges span the neighboring pinnacles. Cliffwatcher Longhorn directs its defense and Freewind braves keep the watch, while an inn, the wind rider master Nyse and a handful of traders make it a welcome stop. The post has troubles enough: centaur raids, the Grimtotem of Darkcloud Pinnacle, harpies and wild serpents. Rau Cliffrunner studies the relics of the centaur, and Hagar Lightninghoof chases rumors of a strange egg.', 'warcraft.wiki.gg/wiki/Freewind_Post (Horde town on a mesa, lifts, rope bridges, centaur warbands, Cliffwatcher leader, Elosai exile); quest 1197 reward text (Rau and the Cloven Hoof); quest 4821 description (Hagar and the egg); quest 9431 description (Elosai); zone_areas 484: Freewind Brave 9525, Cliffwatcher 10537, Nyse 4317, Innkeeper Abeqwa 11116, Rau 4722, Hagar 10539, Elosai 17093, Mesa Elevators'),
(40008, 1, 400, 8, 0, 0, 'The Screeching Canyon', 'West of Freewind Post the land breaks into the Screeching Canyon, a ravine overrun by screeching harpies. Roguefeathers and windcallers haunt its walls, Pesterhide hyenas prowl its floor, and kobolds of the Gravelsnout clan forage among the rocks. At its far end the harpies keep their stronghold, a cavern called the Roguefeather Den. Deep inside, the flock hoards its gathered foodstuffs. Any intruder who spoils that store soon faces the fury of the whole den, and one who survives long enough draws out Grenka Bloodscreech herself.', 'warcraft.wiki.gg/wiki/Screeching_Canyon (harpy infested canyon, Roguefeather Den at its far end); warcraft.wiki.gg/wiki/Roguefeather_Den (cavern full of harpies guarding foodstuffs at the back); quest 1150 description and reward text (Roguefeather Den west of Freewind Post, foodstuffs, Grenka); zone_areas 483: Screeching Harpy, Roguefeather, Windcaller, Pesterhide Hyena, Gravelsnout Forager and Kobold; gameobject 20447 Harpy Foodstuffs; WMOAreaTable maps the cave to 487; quest 1150 description'),
(40009, 1, 400, 9, 0, 0, 'Windbreak Canyon', 'Windbreak Canyon spreads across much of the country between Freewind Post and the Shimmering Flats, a broad stretch of the Needles where elder cloud serpents make their nests. Needles cougars and Pesterhide snarlers hunt among the spires, and the kobold Gibblesnik is sometimes seen skulking about. The serpent dens at the foot of the cliffs may hold more than serpents. Rumor tells of a strange foreign egg hidden in one of them, guarded by the serpents as fiercely as if it were their own, though none who claim to have seen it ever got close enough to look. A ramp climbs the cliffs nearby to the hidden cave of the Weathered Nook.', 'warcraft.wiki.gg/wiki/Windbreak_Canyon (canyon of wind serpents between Freewind Post and the Shimmering Flats; path to the Weathered Nook); quest 4821 description (alien egg in a serpent den, guarded as one of their own); zone_areas 2303: Elder Cloud Serpent, Needles Cougar, Pesterhide Snarler, Gibblesnik 14427, Alien Egg 175565'),
(40010, 1, 400, 10, 0, 0, 'The Weathered Nook', 'North of Freewind Post, where the cliffs look out over the needles, a ramp climbs to a small and well hidden cave called the Weathered Nook. Two tauren make their home here. Dorn Plainstalker receives those who seek to have their spirit, body and mind tested, and the first of his trials begins on planks above the canyon, with a leap that takes faith to make. Beside him lives Prate Cloudseer, a shaman whom the Horde''s teachers send their most promising students to find when they are ready to take up the totem of air and learn to call upon its spirits.', 'warcraft.wiki.gg/wiki/Weathered_Nook (small, well hidden cave, home to Dorn Plainstalker and Prate Cloudseer; reached north of Freewind and up a ramp); quest 1149 description and objective (leap from the planks overlooking Thousand Needles); quests 1531, 1532 descriptions and reward texts (Prate and the air totem); DBC: Dorn display 10969 and Prate display 4541 are tauren models; WMOAreaTable maps the cave to 488'),
(40011, 1, 400, 11, 0, 0, 'The Shimmering Flats', 'At the eastern end of Thousand Needles the canyon opens onto the Shimmering Flats, a dried lakebed of blinding salt that lies below the level of the sea, open and almost bare of plants. Saltstone basilisks, Sparkleshell tortoises and scorpids roam the flats, vultures wheel overhead and whirling vortexes of wind wander across the salt. Wreckage lies everywhere. The gnomes and goblins who race at the Mirage Raceway crash often, and scraps of their rocket cars litter the plain for anyone willing to pick through them. The great basilisk Ironeye the Invincible and the scorpid Vile Sting stalk the flats as well, and to the south a path runs through the mountains toward Tanaris.', 'warcraft.wiki.gg/wiki/Shimmering_Flats (salt flat at the southeastern end, devoid of vegetation, dried lakebed, wreckage and craters from the racers); warcraft.wiki.gg/wiki/Thousand_Needles (below sea level); warcraft.wiki.gg/wiki/Tahonda_Ruins (path through the mountain to Tanaris); quest 1110 description (rocket car parts littered everywhere); zone_areas 439: Saltstone Basilisk, Sparkleshell Tortoise and Snapper, Scorpid Reaver and Terror, Salt Flats Vulture, Swirling Vortex, Rocket Car Rubble, Ironeye 5935 (basilisk faction 49), Vile Sting 5937 (scorpid faction 413)'),
(40012, 1, 400, 12, 0, 0, 'Mirage Raceway', 'Out on the Shimmering Flats lies the Mirage Raceway, a track where gnomes and goblins race their rocket cars against each other to settle whose engineering is better. The dwarf Race Master Kronkrider oversees the races and advises visitors not to bet all their money in one place, while announcers take wagers and Daisy starts the races. Gnome crews mutter that only dumb luck keeps the goblin car from crashing every race, while goblins boast of their tools and talent. Trackmaster Zherin was hired after the goblin racer Red Thunder struck a basilisk, and now keeps the beasts off the course. Vendors sell drinks, ice cream, guns and engineering supplies, and the dwarf Kravel Koalbeard deals in everything else.', 'warcraft.wiki.gg/wiki/Mirage_Raceway (gnomes and goblins competing with rocket cars; Kronkrider a dwarf); npc_text 932 (Kronkrider), 778 and 780 (pit crews); creature_text 4620 (Fobeed taking bets), 4419 (drag race results); quest 1175 description (Zherin hired after Red Thunder crashed into a basilisk); zone_areas 2240: Kronkrider 4419, Daisy 4507, Fobeed 4620, Zuzubee 4707, pit crews, Riznek, Brivelthwerp, Synge, Jinky Twizzlefixxit, Kravel 4452; DBC: Kravel display 5426 and Kronkrider 5445 are dwarf models; npc_text 778 (Goblin Pit Crewman 4429), 780 (Gnome Pit Crewman 4430)'),
(40013, 1, 400, 13, 0, 0, 'The Rustmaul Dig Site', 'In the southwest of the Shimmering Flats lies the Rustmaul Dig Site, where dwarves of the Explorers'' League were excavating until a Horde war party fell upon them and killed them all. The fighting did not end there. The diggers had broken into a cave beneath the site, and from it a swarm of silithid erupted and nearly destroyed the raiders, killing more than half their number. Now hive drones, searchers and invaders crawl over the abandoned dig, and a great silithid ravager is sometimes seen among them. A foul ooze coats the veins of mithril and truesilver that the dwarves left behind.', 'warcraft.wiki.gg/wiki/Rustmaul_Dig_Site (abandoned dwarven dig; Explorers'' League killed by Moktar Krin''s party; silithid nest in a cave); warcraft.wiki.gg/wiki/Shimmering_Flats (dig site in the southwest; dwarves dug into a subterranean hive); quests 1146, 1147 descriptions and 1146 reward text; zone_areas 479: Silithid Hive Drone, Searcher, Invader, Silithid Ravager 4132 (rank 4), Ooze Covered Mithril and Truesilver Deposits'),
(40014, 1, 400, 14, 0, 0, 'Ironstone Camp', 'Ironstone Camp is a small Horde encampment on the edge of the Shimmering Flats, where Moktar Krin and the survivors of his war party wait beside their kodos. They were sent to drive the dwarven excavators out of the Rustmaul Dig Site to the south, and they did, only to see silithid burst from the earth and kill more than half of them. Nag''zehn, Bor''zehn and Tarkreu Shadowstalker are among those left. Too battered to fight, they hold their position and wait for word from Belgrom Rockmaul in Orgrimmar, while the thunder of the races echoes off the mountain walls. Moktar counts those races as atrocities born of what the racers call science.', 'warcraft.wiki.gg/wiki/Ironstone_Camp (small Horde group sent to drive out the excavators; NPCs); quest 1146 description and reward text (war party, more than half killed, waiting for word from Belgrom, races as atrocities of science); quest 1147 description and completion text (dig site to the south, half dead war party); zone_areas 3037: Moktar Krin 4483, Nag''zehn 4545, Bor''zehn 4546, Tarkreu Shadowstalker 4547, War Party Kodo 5523'),
(40015, 1, 400, 15, 0, 0, 'Tahonda Ruins and Weazel''s Crater', 'Beyond the raceway the Shimmering Flats keep a few lonely landmarks. The Tahonda Ruins were once a tauren village, but they fell to ruin long ago and have half slipped beneath the salt and sand. No one now knows for certain why the village was abandoned. Saltstone gazers and crystalhides lurk among its broken buildings, and some suspect the basilisks themselves drove its people away. In the north of the flats lies Weazel''s Crater, a large, deep pit home to more basilisks. Who or what made it is a mystery, though the scraps of rocket car scattered around it hint at one of the racers'' less stable inventions.', 'warcraft.wiki.gg/wiki/Tahonda_Ruins (tauren village that came to ruin beneath the sands; basilisks possibly the reason it was abandoned); warcraft.wiki.gg/wiki/Weazel''s_Crater (large deep crater in the northern flats; origin unknown, perhaps an unstable invention); zone_areas 3039: Saltstone Crystalhide, Gazer, Rocket Car Rubble; 3038: Saltstone Basilisk, Crystalhide, Rocket Car Rubble'),
(40016, 2, 400, 1, 2, 0, 'Cliffwatcher Longhorn', 'Cliffwatcher Longhorn keeps watch over Freewind Post, and his patience with the enemies around it has worn thin. The Galak centaur harry the roads, and the Grimtotem of Darkcloud Pinnacle are up to something secret: three agents of unknown origin have been seen visiting them, and the strangers'' guarded messages are said to be locked away in separate chests up on the pinnacle. The bounty on the murderer Arnak Grimtotem is his to pay. After a year without writing, he is sending word of the centaurs'' unrest to his brother Nataka, stationed far away at Ghost Walker Post in Desolace.', 'quest 4542 reward text (caravan slaughtered, will not go unpunished); quest 4841 description; quest 5064 description and reward text; quest 5147 (Wanted poster, turned in to Longhorn); quest 5361 description (brother Nataka at Ghost Walker Post, a year since last writing, unusual centaur activity); warcraft.wiki.gg/wiki/Freewind_Post (Cliffwatcher Longhorn leader)'),
(40017, 2, 400, 2, 0, 0, 'Arnak Grimtotem', 'Arnak Grimtotem is the Grimtotem of Darkcloud Pinnacle whom Freewind Post most wants to see dead. A wanted poster at the post names him an outcast, guilty of the heinous crimes of murder and kidnapping, and promises a handsome reward to anyone brave enough to bring him to justice. He was last seen on the cliffs near the pinnacle, among the stompers and geomancers of his tribe, and Cliffwatcher Longhorn stands ready to pay the bounty to whoever brings proof of the deed.', 'gameobject 176115 and quest 5147 description and reward text (Arnak the outcast, murder and kidnapping, last seen on the cliffs near Darkcloud Pinnacle); quest 4904 description (kidnapping, brother slain); creature_text 10646 (strange power over the Grimtotem); warcraft.wiki.gg/wiki/Darkcloud_Pinnacle (leaders Arnak and Harb Foulmountain); zone_areas 2097: Arnak Grimtotem 10896; gameobject 176115 spawned at Freewind Post (-5458,-2457); warcraft.wiki.gg/wiki/Arnak_Grimtotem (outcast; ''Chief of all Darkcloud Grimtotem Chiefs'' title and elite stats are Cataclysm)'),
(40018, 2, 400, 3, 2, 0, 'Dorn Plainstalker', 'Dorn Plainstalker is a tauren sage who lives in a hidden cave in the cliffs overlooking Thousand Needles. He holds that a being is made of many facets, spirit, body and mind, and that some of them can be measured by a people''s traditions while others we can only hope exist within ourselves. He considers it his duty to the young of every tribe to prepare them for the dangers they will meet once they leave the shelter of home, for too often, he says, they rush ahead before they are ready. Above all he prizes faith, and holds that it hardly matters what one believes, only that one believes in something.', 'quest 1149 description and completion text (facets, faith); quest 1150 completion text (duty to the youth of every tribe, rushing forward before ready); warcraft.wiki.gg/wiki/Weathered_Nook and Dorn_Plainstalker (Horde tauren in the Weathered Nook); DBC: display 10969 tauren male'),
(40019, 2, 400, 4, 2, 0, 'Braug Dimspirit', 'Braug Dimspirit is a tauren shaman of great wisdom who dwells in the Stonetalon Mountains, near the mouth of the Talondeep Path. He gives the Test of Lore that Dorn Plainstalker leaves to others, and he has small regard for trials of the body, which he calls childish beside a test of the mind. The days and nights grow colder, he says, while goblins ravage the land and the night elves point fingers at the younger races, but the Forsaken and the orcs are not the only ones to blame: many of the thinking races have added to the world''s pain.', 'quest 1152 description and reward text (shaman of great wisdom near the Talondeep Path; world''s pain); quest 1154 description (body tests childish, test of the mind); npc_text 5820 (question about the Aspect who became Deathwing); stonetalon.json 40615 (Braug left to Thousand Needles); DBC: display 3907 tauren male'),
(40020, 2, 400, 5, 0, 0, 'Rok''Alim the Pounder', 'As Dorn Plainstalker tells it, in the age of the Old Gods elementals filled much of the world, worshipping those gods and held here by their power. When the Old Gods were banished, most faded away and now return only at the bidding of powerful mages. A few were strong enough to remain on their own, and Rok''Alim is one of them, a great elemental of living rock who wanders the western canyon. The centaur tribes call him the Pounder, for the thundering of his fists as he beats down any creature brave or foolish enough to stand in his path. To Dorn he is the measure of a true test of strength.', 'quest 1151 description and completion text (Old Gods and elementals; the Pounder); DBC: display 4766 ElementalEarth model; DB spawn 4499 at -5202,-1569 (northwest of Freewind Post, area 400)'),
(40021, 2, 400, 6, 2, 0, 'Wizlo Bearingshiner', 'Wizlo Bearingshiner is a goblin of Whitereach Post and the only survivor of a caravan the centaurs fell upon just north of the camp. The raiders took everything except his best gizmo, a hypercapacitor that now hangs from the neck of a rare and mighty panther, a beast so ferocious that even the centaurs tremble before it and left it alone in its cage. Wizlo still holds the key to that cage, and he wants his gizmo back.', 'quest 5151 description and reward text; quest 9431 reward text (her money is as gold as anyone else''s; only client he has); quest 9433 description and reward text (Robotron, client would hang me by my ears); zone_areas 2237: Wizlo 10941, Robotron 3000 17178; gameobject 176195 Panther Cage, Enraged Panther 10992'),
(40022, 2, 400, 7, 0, 0, 'Fizzle and Wizzle Brassbolts', 'The gnome brothers Fizzle and Wizzle Brassbolts build the gnome rocket car of the Mirage Raceway, the fastest thing on the Shimmering Flats, so fast that its pilots keep crashing. Fizzle is the dreamer, bubbling over with designs and certain that one day the car will fly, chasing fuels that burn ever hotter and engines that need pistons harder than any he can make. Wizzle is the worrier who follows behind him, building tanks his brother''s fuel will not eat through and a coating to keep the car from being torn apart by its own speed. Rizzle Brassbolts pores over their newest plans. Most days they win, since the goblin car blows up so often.', 'quests 1104, 1105, 1106, 1107 descriptions; quest 1179 description (pilots keep crashing, concussions); quest 2769 description (they usually win; goblin car blows up); quest 1190 description (Rizzle focused on the plans); zone_areas 2240: Fizzle 4454, Wizzle 4453, Rizzle 4720'),
(40023, 2, 400, 8, 0, 0, 'Pozzik', 'Pozzik builds the racers of the goblin team at the Mirage Raceway, a team he calls the pride of goblins everywhere. He was one of the most respected tinkerers in Undermine before he retired to work on racers, and the first thing he did when he joined the team was develop the two engine model. Every ounce counts with him: he lightens his frames with hollow vulture bones from the salt flats, and Gazlowe of Ratchet is among the team''s sponsors, tracking down parts for it from around the world. He is cautious enough to put a bucket of sand under his pilot''s seat, which his pilot hates. That pilot, Razzeric, is the eighteenth the team has had.', 'quest 1178 description and reward text (pride of goblins, respected Undermine tinkerer, two engine racers); quest 1176 description (vulture bones); quest 1182 reward text (Revilgaz as sponsor); quest 1186 description (eighteenth pilot); quest 1189 completion text (bucket of sand); quest 1187 description (Pozzik''s a great mechanic); quest 1178 description (Gazlowe tracks down parts)'),
(40024, 2, 400, 9, 0, 0, 'Kravel Koalbeard', 'Kravel Koalbeard is a dwarf who has made the Shimmering Flats his marketplace. He pays for the scrap of crashed rocket cars and sells it on to gnomes and goblins forever hungry for more contraptions, and his advice comes free of charge: there is always profit to be found in someone else''s tragedy. He fills special orders for the racing teams, and sends deliveries as far as Stranglethorn, where Hemet Nesingwary Jr. waits on a package that took weeks to reach the flats. Junior is a rich dwarf, Kravel reasons, and it pays to keep up relations with the rich.', 'quest 1110 description and reward text; quest 1114 description (removed a piece from the order); quest 5762 description, completion and reward text; quests 1118, 1122 (Booty Bay scheme); DBC: display 5426 dwarf male'),
(40025, 3, 400, 1, 2, 0, 'The Four Tests', 'In his cave above the Needles, Dorn Plainstalker offers to test the seekers who find him, in spirit, in body and in mind, and to see what each holds within. Pass, he promises, and you will grow stronger; fail, and you will learn the vastness of the Nether. His trials begin with a Test of Faith. The seeker must leap from the planks overlooking Thousand Needles with no promise of surviving the fall, trusting only in what they believe. Faith, Dorn says, is far more important than some realize.', 'quests 1149, 1150, 1151, 1152, 1154, 6627, 1159, 1160, 6628, 1394 descriptions and reward texts; npc_text 5820, 5822 (Braug''s and Parqual''s questions); undercity.json 149709 (Parqual person entry, mentioned only); quest 1149 completion text'),
(40026, 3, 400, 2, 2, 0, 'The Sacred Flame', 'The Galak centaur of Thousand Needles guard an artifact from the time of their race''s creation, and Rau Cliffrunner of Freewind Post means to have it. To reach it he needs water from a night elf moonwell, and he has asked his associate Zangen Stonehoof in Thunder Bluff to find someone to fetch it. The seeker must first win an etched phial from one of the dryads near Raynewood Retreat, in the heart of Ashenvale, then fill it at a moonwell on the western bank of the Falfarren River, south of the main road, and bring it back to Zangen, who will send it on to Rau.', 'quest 1195 description and completion text; quest 1196 description and reward text; quest 1197 description and reward text'),
(40027, 3, 400, 3, 2, 0, 'Vengeance in the Needles', 'A rumor has spread through Freewind Post of a strange egg in Thousand Needles, unlike any other. It lies, so the reports say, in one of the serpent dens along the base of the cliffs south and northeast of the post, guarded by the cloud serpents as though it were one of their own brood, and no one who reports seeing it has managed a closer look. Hagar Lightninghoof means to find out what it is. He wants the egg brought to him so that he can examine it, for he must know what will hatch from it.', 'quest 4821 description and reward text; quest 4865 description and reward text; quest 5062 description, completion text and reward text; quest 5088 description and reward text; warcraft.wiki.gg/wiki/Arikara (egg hatched at Freewind; classic events only); creature 10882 Arikara, subname Vengeance; thunder_bluff.json 163807 (Magatha entry already tells her Cairne claim); quest 4821 description and completion text'),
(40028, 3, 400, 4, 2, 0, 'The Centaur Raids', 'The Galak centaur have stepped up their attacks around the Great Lift, and the braves who guard it are alarmed. Brave Moonhorn sends an urgent message down the road to Cliffwatcher Longhorn at Freewind Post, with a warning to steer clear of the nearby Grimtotem, who have been acting strangely toward the tauren of late. The Galak hold Camp E''thok in the northwest and their chief village, Splithoof Crag, north of Freewind itself, and the tauren who make their homes in the Needles are never out of reach of their raids.', 'quest 4542 description and reward text; quest 4841 description and objectives; item 12564 Assassination Note (dropped by Galak Messenger 10617, 100 percent) starts quest 4881; 4881 description and reward text; quest 4966 description and reward text; creature_text 10638; quest 4542 description (Grimtotem acting strange)'),
(40029, 3, 400, 5, 2, 0, 'Free at Last', 'Arnak Grimtotem decided that Lakota Windsong of Freewind Post would be his bride. When she refused him he came back that same night and took her. Her brother tried to stop him and was slain, and Arnak carried her off to Darkcloud Pinnacle as his captive. There she waits among the Grimtotem, mourning her brother and thinking of Thalia Amberhide at Freewind Post, who must be sick with worry about her. She asks any stranger who reaches her to lead her out of the pinnacle, so that she can find her way home.', 'quest 4904 description and reward text; creature_text 10646 (strange power, Grimtotem ambushes, can return alone); zone_areas 2097: Lakota Windsong 10646; 484: Thalia Amberhide 10645'),
(40030, 3, 400, 6, 2, 8, 'The Magistrix''s Tonic', 'Magistrix Elosai is a sin''dorei far from Silvermoon, living on a windswept butte in Thousand Needles because her own people will no longer have her. She wrote a treatise on natural cures for the blood elves'' addiction to magic, and every copy was burned. Here she can pursue her research in safety, if only someone will gather her reagents. The first is purifying earth, taken from the thundering boulderkin at the western end of the Needles and carried to her associate at Whitereach Post, the goblin Wizlo Bearingshiner, who will know what to do with it.', 'quest 9431 description and reward text; quest 9433 description and reward text; quest 9434 description and reward text; creature_text 17093 (the tonic hastens her descent into the Wretched)'),
(40031, 3, 400, 7, 0, 0, 'Kravel''s Scheme', 'Kravel Koalbeard sees profit in every corner of the Shimmering Flats, and he makes it his job to get people what they need. Just now the gnomes of the Mirage Raceway need a parts order filled. Their parts were shipped to Ratchet a week ago, but Kravel has not been able to make the trip, so he looks for someone ready for a little legwork: take his order to Wharfmaster Dizzywig at the Ratchet docks and bring the package back. Do this, he promises, and there will be more jobs, jobs with serious profit potential.', 'quests 1111, 1112, 1114 descriptions and reward texts; quests 1115, 1117 descriptions and reward texts; page_text 438 (Goblin Rumors); quest 1118 description; page_text 439, 445, 446 (Kravel''s Scheme letter); quests 1119, 1120, 1121, 1122 descriptions and reward texts; creature_text 4452'),
(40032, 3, 400, 8, 0, 0, 'The Indurium Race', 'Fizzle Brassbolts dreams of a fuel that burns hotter than any before, made from the salty venom of the scorpids on the flats, while his brother Wizzle fears it will eat straight through the chassis and builds new tanks from the hard shells of the flats'' tortoises. A faster engine needs pistons that can take tremendous stress, and every piston Fizzle has made has failed. So he writes to Martek the Exiled in the Badlands, a great smith who knows more about metal than anyone, sure that Martek can help. Across the pits, the goblin team watches every gnome run.', 'quests 1104, 1105 descriptions (exclusive group, both lead to 1106); quest 1106 description (Martek), 1108, 1137 descriptions; creature_text 4454 (indurium is the key); quest 1190 description, 1191, 1194 description and reward text; quest 1192 completion text; creature_text 4709, 4720'),
(40033, 3, 400, 9, 0, 0, 'Goblin Sponsorship', 'The goblin racing team at the Mirage Raceway needs every edge it can get, for the gnomes are gaining on them. To Pozzik, who builds its racers, everything counts: a minor tweak to the power output, a slight slackening of the tension coils, a lighter frame. He makes many of his small structural changes with hollow vulture bones, which offer the perfect balance of strength and weight and are easy to come by, since the salt flats are littered with vultures. Whatever else the racers need comes from the team''s sponsors.', 'quest 1176 description; quests 1178, 1180, 1181, 1182, 1183 descriptions and reward texts; quest 1186 description and reward text; quests 1187, 1188, 1189 descriptions, reward and completion texts');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(40002, 1, 0, 255, 'The chests gave up their secrets. The messages are letters to one Agasham of the Grimtotem, signed by three who call themselves Harbingers. Their affiliation must be hidden at all costs, for it would be a disaster if the other tauren tribes learned of it. Together, the letters promise, their forces will be mightier than all the tribes combined, if the clan obeys completely, and agents from Lordaeron are soon to meet its delegates at a summit.', 'page_text 2232, 2233, 2234 (Secret Notes); quest 5064 reward text'),
(40004, 1, 0, 255, 'The Galak have marked Kanati for death. A note taken from one of their messengers calls him bold for setting up his hunting camp in the Needles and orders him killed, to be rid of the camp and anyone who might follow him, and it names this very post as the place where the assassins will gather.', 'quest 4881 description (item 12564 Assassination Note)'),
(40004, 2, 8, 255, 'Since the blood elves joined the Horde, the post has a stranger resident still. Among the goods Wizlo keeps here stands a crated machine of goblin make, the Robotron 3000, which he was carrying for another of his clients, and the goblin has lately taken on work for an exiled blood elf at Freewind Post.', 'zone_areas 2237: Robotron 3000 17178; quests 9431, 9433 descriptions'),
(40006, 1, 0, 255, 'The flame can be beaten, for a little while. The dryads and the centaur share a common ancestry, and so water drawn from a night elf moonwell can breach the eternal fire around the Cloven Hoof. It will not hold for long, and whoever carries it into Splithoof Hold must be quick before the flame returns.', 'quest 1196 reward text (shared ancestry); quest 1197 description (temporary)'),
(40007, 1, 8, 255, 'Since the blood elves joined the Horde, a sin''dorei has made her home on a windswept butte at the post. Magistrix Elosai was cast out by her own people, who burned every copy of her treatise, and here she seeks in safety a natural cure for their addiction to magic.', 'quest 9431 description'),
(40016, 1, 0, 255, 'Brave Moonhorn''s warning came on a bad day for Longhorn. The centaurs had just fallen on one of his own supply caravans and killed every member of the party. He called it an outrage that would not go unpunished, and he sought fighters to make the centaurs at the camp north of Freewind feel his wrath.', 'quest 4542 reward text; quest 4841 description'),
(40016, 2, 0, 255, 'When the Grimtotem''s secret messages were stolen and laid before him, Longhorn called on the Great Spirit Totem. The news they held was dire indeed, he said, and he began at once to plan for whatever may come.', 'quest 5064 reward text'),
(40016, 3, 0, 255, 'When proof of Arnak Grimtotem''s death was brought to him, Longhorn could hardly contain his delight. He had begun to think the murderer would never be brought to justice, and news of Arnak''s foul deeds had boiled his blood.', 'quest 5147 reward text'),
(40017, 1, 0, 255, 'His captive tells the rest. Lakota Windsong of Freewind Post refused to become his bride, so Arnak returned by night and carried her off to the pinnacle, cutting down her brother, who tried to stand in his way. Outcast he may be, she warns, but he holds some strange sway over the Grimtotem there, and they will not take kindly to her leaving.', 'quest 4904 description; creature_text 10646 (strange power over the Grimtotem)'),
(40017, 2, 0, 255, 'In the end Arnak Grimtotem fell on the cliffs near Darkcloud Pinnacle, brought down in the heights of his own clan''s stronghold. The outcast named on Freewind Post''s wanted poster will trouble the Needles no longer.', 'zone_areas 2097: Arnak Grimtotem 10896; quest 5147'),
(40021, 1, 0, 255, 'The hypercapacitor came back to him at last, taken from the panther''s neck. Wizlo is overjoyed to have it, and it will keep him busy for a good while, he admits, until he can work out what it actually does.', 'quest 5151 reward text'),
(40021, 2, 8, 255, 'In this age Wizlo has found work with the exiled blood elf Magistrix Elosai of Freewind Post, the only client he has left, and her money, he says, is as gold as anyone else''s. For her he unpacked a Robotron 3000 he was carrying for someone else, and he dreads what that client would do if he ever found out.', 'quest 9431 reward text; quest 9433 description'),
(40024, 1, 0, 255, 'His special orders are not always honest. When a parts order for the Brassbolts brothers finally reached him from Ratchet, Kravel took out one small item before sending the rest on, and told the courier not to bother mentioning it to Fizzle.', 'quest 1112 reward text; quest 1114 description; creature_text 4452'),
(40024, 2, 0, 255, 'In Stranglethorn, Hemet Nesingwary Jr. was glad of the crate of special gauge ammunition, which would serve him well in the jungle. He asked after crusty old Kravel, wagering that the dwarf was still up to no good.', 'quest 5762 reward text'),
(40024, 3, 0, 255, 'Kravel is indeed up to something. He has a scheme afoot with Booty Bay: dull the wits of one pit crew, let its car slip into disrepair before a race, and wager on a result he has already decided.', 'page_text 439, 445, 446 (Kravel''s Scheme)'),
(40025, 1, 0, 255, 'The leap was made. Only in the face of unforeseen adversity, Dorn says, do we learn how strong our spirits are, and the seeker''s mind is open and ready. Next he tests the body. In the Roguefeather Den west of Freewind Post the seeker must spoil the harpies'' hoarded food and outlast their fury until Grenka Bloodscreech herself comes to fight.', 'quest 1149 reward text; quest 1150 description'),
(40025, 2, 0, 255, 'Grenka''s claw was brought back, and Dorn praised the endurance shown against the Roguefeathers. Strength came next. Rok''Alim is an elemental who stayed in the world when the Old Gods were cast out and most of his kind faded, and the centaur name him the Pounder for his thundering fists. To prove their strength, the seeker had to slay him.', 'quest 1150 reward text; quest 1151 description and completion text'),
(40025, 3, 0, 255, 'With Rok''Alim fallen, one test remained, and it was not Dorn''s to give. He sent his pupil north to Braug Dimspirit, a shaman of great wisdom who dwells near the tunnel joining Stonetalon with Ashenvale, and warned that the night elves might try to hinder the test.', 'quest 1151 reward text; quest 1152 description'),
(40025, 4, 0, 255, 'Braug thought little of the trials so far. The body is easily tested, he said, the mind is another matter. He named a book, the Legacy of the Aspects, kept at the bottom of Dor''danil in southern Ashenvale among dead druids and their slayers, and told the seeker to find it, study it and answer his question on its contents.', 'quest 1152 reward text; quest 1154 description'),
(40025, 5, 0, 255, 'His question, when it came, was which of the Aspects created by the titans became the creature known as Deathwing. Answered well, it earned the next step: Braug sent the seeker to the Undercity, to Parqual Fintallas, a great historian of the humans before the Plague overtook him, who would ask the final question himself.', 'npc_text 5820; quest 6627 reward text; quest 1159 description'),
(40025, 6, 0, 255, 'Parqual scoffed at the tale of leaps and elementals and took the seeker for a farce. Still, knowledge mattered more than strength to him, and he set his own task: bring him Beginnings of the Undead Threat, a book from the library of the Scarlet Monastery that its now corrupt paladins once used to train against his kind.', 'quest 1159 reward text; quest 1160 description'),
(40025, 7, 0, 255, 'With the book in his hands, Parqual asked which creature became the Lich King before spreading the plague across Lordaeron. He had doubted the seeker had studied, but the answer was right. The more you know, he says, the more you will see, and he sent the student back to Dorn, who would sense the change within.', 'npc_text 5822; quest 6628 completion and reward text; quest 1394 description'),
(40025, 8, 0, 255, 'Dorn felt that many moons had passed since his pupil first leapt from the planks. The one who stood in his cave again was stronger and more enlightened, and having seen his tests through to the end, deserved reward. Stay true to the balance, Parqual had counselled, and Dorn may one day test them again.', 'quest 1394 description and reward text'),
(40026, 1, 0, 255, 'The phial served Rau''s purpose perfectly. Because the dryads and the centaur share an ancestry, he explained, the moonwell''s water would let him breach the eternal flame around the relic, the Cloven Hoof, kept in Splithoof Hold north of the post. It would douse the flame only for a short time, and the crag''s defenders are many.', 'quest 1196 reward text; quest 1197 description'),
(40026, 2, 0, 255, 'With the flame doused, the seeker forced a way into the Galak stronghold and took the Cloven Hoof. Rau feels a strange energy pouring from it, sure it will reveal surprising things about the centaur, and he sets to work at once on the mysteries it holds.', 'quest 1197 reward text'),
(40027, 1, 0, 255, 'The egg was brought to Hagar, and as he looked closer, something burst forth that he could scarcely believe. Vengeance had come to Thousand Needles, he cried, and he sent word in haste to Motega Firemane at Whitereach Post, who would know what to do.', 'quest 4821 reward text; quest 4865 description'),
(40027, 2, 0, 255, 'Motega knew the legend of Arikara and now knew it to be true. She had to be dealt with swiftly. To summon her the dormant Sacred Fire of Life must be lit, and for that, rare Incendia agave from the Boiling Pool had to be enchanted into a powder by Magatha Grimtotem, the powerful shaman of Elder Rise in Thunder Bluff.', 'quest 4865 reward text; quest 5062 description'),
(40027, 3, 0, 255, 'Magatha called the news grave. Arikara, she said, is a deadly creature born only to seek vengeance against those who have committed heinous acts. She glanced about her and smiled, then began to enchant the agave.', 'quest 5062 completion and reward text'),
(40027, 4, 0, 255, 'The powder was to be cast upon the sacred fire on the isolated needle where the Grimtotem of Darkcloud Pinnacle bury their dead. Magatha had a warning to send with it: she feared Arikara was stalking Cairne Bloodhoof, for too much tauren lore had changed, and that had angered the serpent.', 'quest 5088 description'),
(40027, 5, 0, 255, 'The fire was lit, the serpent came, and Arikara was slain. Motega could make no sense of it. Why would Arikara be after Cairne Bloodhoof? Yet he shook his head and set his doubt aside, for Magatha could not be wrong: she was their most powerful shaman.', 'quest 5088 reward text'),
(40028, 1, 0, 255, 'The message reached Longhorn hard on the heels of worse news: centaurs had raided one of his supply caravans and slaughtered the whole party. He wanted vengeance, and sent fighters against the Galak camp north of the post to cut down their scouts, wranglers and windchasers.', 'quest 4542 reward text; quest 4841 description and objectives'),
(40028, 2, 0, 255, 'The centaurs were planning a killing of their own. A Galak messenger carried their orders against Kanati Greycloud, who had dared to set up a hunting camp in the Needles: the assassins would converge on his small post southwest of the Great Lift, to be rid of him and of all who might follow him.', 'item 12564 Assassination Note, quest 4881 description'),
(40028, 3, 0, 255, 'Warned in time, Kanati swore to show the centaurs how a tauren fights. Yet more of them were coming than he had thought, and he asked for a blade beside his own against the assassins.', 'quest 4881 reward text; quest 4966 description'),
(40028, 4, 0, 255, 'The Galak came to Whitereach Post as the note had promised, and they were held off. Kanati gave his thanks freely to the one who stood with him, admitting that he could never have held them back alone.', 'quest 4966 reward text; creature_text 10638'),
(40029, 1, 0, 255, 'The escape was hard won. Arnak had some strange power over the Grimtotem, Lakota warned, and they would not be happy to see her go: band after band of them fell upon her and her rescuer on the way down. Once she was free she hurried home alone. Thalia had known deep in her bones that Lakota would find her way back, and she thanked the rescuer with the belongings of Lakota''s dead brother, which she knew Lakota would want them to have.', 'creature_text 10646; quest 4904 reward text'),
(40030, 1, 0, 255, 'Elosai''s note to Wizlo was cryptic, but he understood. She wanted water from the night elves'' moonwell at Thalanaar. He would not send anyone in openly with a flask: instead a Robotron 3000, a machine he was carrying for another client, would scoop up the water, steered from a console he had hidden in the bushes on the rim of the needle nearest Thalanaar.', 'quest 9431 completion and reward text; quest 9433 description and objectives'),
(40030, 2, 0, 255, 'With every reagent gathered, Elosai mixed her tonic, raised a toast to a brighter future and drank. It did not cure her. It hastened her descent toward the ranks of the Wretched instead, and in despair she wondered whether all her years of research had been for nothing, and whether this was something her people must simply learn to live with.', 'quest 9434 reward text; creature_text 17093'),
(40031, 1, 0, 255, 'The parts had sat on the docks for days. Once they were back, Kravel helped himself to one small piece, slipping it into his pocket, and only then passed the rest along to Fizzle Brassbolts.', 'quests 1111, 1112 reward texts; quest 1114 description; creature_text 4452'),
(40031, 2, 0, 255, 'Fizzle was delighted with his hydro ratchets and repeater bolts and seemed none the wiser. Next Kravel wanted leverage over the goblins. Their pilot Nazz Steamboil had not always gone by that name, and Krazek of Booty Bay spent favors and a rare bottle of elven wine to learn why: Nazz is the son of a merchant prince, hiding on the flats with a small fortune stolen from his family. If Nazz valued that secret, Kravel meant to turn a profit from it.', 'quest 1114 reward text; quest 1115 description; quest 1117 description; page_text 438 (Goblin Rumors, item given on accepting 1117)'),
(40031, 3, 0, 255, 'Then came the real scheme, set out in a letter to Crank Fizzlebub of Booty Bay. The rocket cars need constant care, so if one pit crew could be made to slacken, its car would soon fall into disrepair, and a man who knew which car would fail could bet accordingly. Kravel wanted something to addle the wits of gnomes and goblins.', 'quest 1118 description; page_text 439, 445, 446 (Kravel''s Scheme)'),
(40031, 4, 0, 255, 'Fizzlebub found it in the mixture Zanzil feeds his zombies, brewed into a powerful Fool''s Stout. Carried to the raceway, it was gratefully accepted by one of the pit bosses, who saw no harm in just a little.', 'quests 1118, 1119 reward texts; quests 1120, 1121 reward texts'),
(40031, 5, 0, 255, 'The stout worked. Kravel laid his bet on the next race, hoping the crew had done a number on their own car, and sent word of the successful test back to Fizzlebub, who was glad of the news and offered to brew more whenever it was wanted.', 'quest 1122 description and reward text'),
(40032, 1, 0, 255, 'The gnome car grew faster, yet its design and every reading the goblins took from its runs looked the same as before. Pozzik decided the Brassbolts had found a new building material. Rizzle Brassbolts did little but pore over the plans for it, so Zamek of the goblin team stood ready to make a diversion while someone stole them.', 'quest 1190 description'),
(40032, 2, 0, 255, 'Zamek''s noisy blast drew Rizzle off to see the damage, and the plans were taken. Rizzle''s schematics described how to refine indurium ore, drawn from the dwarven dig at Uldaman in the Badlands, and dwelt on its resistance to heat. Under the plans, used as a paperweight, sat a hunk of raw indurium. Pozzik saw at once that it explained the gnomes'' new speed, and that he would need much more of the ore, mined from Uldaman, before it could be of use to his own team.', 'quest 1194 description and reward text; quest 1192 completion text; creature_text 4709, 4720; quest 1190 reward text'),
(40033, 1, 0, 255, 'Weeks ago Gazlowe of Ratchet, who tracks down parts for the team from around the world, promised Pozzik a new prototype fuel regulator. It never came, and Gazlowe is usually prompt, so Pozzik sent a helper to Ratchet to ask after it, for the gnomes are gaining and he cannot afford to wait.', 'quest 1178 description'),
(40033, 2, 0, 255, 'Gazlowe in turn had been waiting on Baron Revilgaz of Booty Bay to ship the part. The trail ran to the Booty Bay docks, where Wharfmaster Lozgil found no record of any race parts, and on to the Baron himself. His men had come back empty handed from their hunt for the blueprints, but he knew where they were: the Venture Company shredders at Lake Nazferiti in Stranglethorn run on the new regulator, and their foreman Cozzle keeps the plans locked in his house.', 'quest 1180 description and reward text; quest 1181 reward text; quest 1182 description'),
(40033, 3, 0, 255, 'The blueprints were stolen from Cozzle''s house. Revilgaz copied them for his own notes and sent them on to Pozzik with his regards, not wanting him to think a sponsor had abandoned him, and said he would be waiting for news of a new track record.', 'quest 1182 reward text; quest 1183 description (RewardNextQuest of 1182)'),
(40033, 4, 0, 255, 'Pozzik had hoped for a finished part, but he took the chance to improve the design from the ground up. His pilot Razzeric, the team''s eighteenth, wants more than Pozzik dares to give. He loosens the controls and strips the frame of his racers, and he has ordered a seaforium booster from Shreev of the Gizmorium in Gadgetzan, only for the zeppelin carrying it to crash in Dustwallow Marsh.', 'quest 1183 reward text; quest 1186 description and reward text; quest 1187 description'),
(40033, 5, 0, 255, 'The booster was recovered, but Razzeric wanted its safety off. Shreev, who had already made it deliver more of its payload, did what was asked and sent a warning back: one slip and Razzeric will be a burnt spot on the track. Razzeric was delighted, sure he would set a new course record.', 'quest 1188 description and reward text; quest 1189 description and reward text');
